import React from 'react';
import { ArrowRight, Cpu, Zap, Monitor, Wrench, Building } from 'lucide-react';

const departments = [
    { name: "Computer Science & Engineering", icon: Monitor, description: "Innovating the future through intelligent computing and software engineering." },
    { name: "Electronics & Communication", icon: Cpu, description: "Pioneering advancements in communication networks and embedded systems." },
    { name: "Electrical & Electronics", icon: Zap, description: "Powering the world with sustainable energy systems and smart grids." },
    { name: "Mechanical Engineering", icon: Wrench, description: "Building the foundation of modern machinery and thermal systems." },
    { name: "Civil Engineering", icon: Building, description: "Designing and constructing sustainable infrastructure for tomorrow." },
    { name: "Information Technology", icon: Monitor, description: "Bridging the gap between computing theory and real-world applications." }
];

const Programs = () => {
    return (
        <section id="departments" className="py-24 bg-slate-50">
            <div className="max-w-7xl mx-auto px-6">
                <div className="text-center mb-16">
                    <span className="text-gold font-bold tracking-[0.2em] uppercase text-sm mb-3 block">Academics</span>
                    <h2 className="text-4xl md:text-5xl font-display font-extrabold text-coral">Our Departments</h2>
                    <div className="w-20 h-1.5 bg-gradient-to-r from-coral via-gold to-coral mx-auto mt-6 rounded-full"></div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {departments.map((dept, index) => (
                        <div key={index} className="group relative bg-white rounded-2xl p-8 shadow-[0_4px_24px_rgba(48,54,79,0.06)] hover:shadow-[0_12px_40px_rgba(48,54,79,0.12)] transition-all duration-500 transform hover:-translate-y-2 border border-slate-100 overflow-hidden">
                            {/* Decorative animated top border */}
                            <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-coral to-gold transform origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-500 ease-out"></div>

                            <div className="relative z-10">
                                <div className="w-16 h-16 rounded-xl bg-slate-50 border border-slate-100 flex items-center justify-center text-coral mb-6 group-hover:scale-110 group-hover:bg-coral group-hover:text-white group-hover:border-coral transition-all duration-500 shadow-sm">
                                    <dept.icon size={28} strokeWidth={1.5} />
                                </div>

                                <h3 className="text-xl md:text-2xl font-bold text-coral2 mb-4 font-display group-hover:text-coral transition-colors">{dept.name}</h3>
                                <p className="text-slate-500 mb-8 leading-relaxed font-body">
                                    {dept.description}
                                </p>
                            </div>

                            <div className="absolute bottom-8 left-8">
                                <a href="#" className="inline-flex items-center text-coral font-bold uppercase text-sm tracking-wider hover:text-gold transition-colors">
                                    Explore <ArrowRight size={18} className="ml-2 transform group-hover:translate-x-2 transition-transform duration-300" />
                                </a>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default Programs;
